from gl import *
UNIT = Unit(5, "Functions and Parameters", "Name a piece of code, give it inputs, get an answer back, and reuse other people's libraries.",
    "Big Idea 3: Algorithms and Programming", "#7C3AED", "#6D28D9", "#A78BFA", "#EDE9FE", "rings",
    ["Define and call functions, and explain parameters and arguments", "Write functions with several parameters and know why order matters",
     "Return values and tell return apart from print", "Combine return with decisions and loops", "Use libraries and read API documentation", "Describe procedural abstraction for the Create Task"],
    [F("5.1", "functions-parameters.html", after=[see(anatomy("Anatomy of a function header", [("def", "Keyword", "Tells Python you are defining a function."), ("greet", "Name", "How you call it later."), ("(name)", "Parameter", "A variable that receives a value when the function runs."), (":", "Colon", "Ends the header. The body is indented below it.")], size=30, caption="The header names the function and lists its parameters."),
            annot_code("Define once, call many times", "def greet(name):\n    print(\"Hi \" + name)\n\ngreet(\"Ana\")\ngreet(\"Ben\")",
              [(0, "name", "The PARAMETER: a variable that receives a value."), (1, "print(\"Hi \" + name)", "The body is indented. It uses the parameter."), (3, "\"Ana\"", "The ARGUMENT: the real value sent in. It is stored in name.")], output=["Hi Ana", "Hi Ben"], caption="A parameter is the slot. An argument is what you put in it."))]),
     F("5.2", "multiple-parameters.html", after=[see(annot_code("Order matters", "def power(base, exp):\n    return base ** exp\n\nprint(power(2, 3))\nprint(power(3, 2))",
              [(0, "base, exp", "Two parameters, filled in order."), (3, "2, 3", "base = 2 and exp = 3, so 2 ** 3 = 8."), (4, "3, 2", "Swapped arguments give a DIFFERENT answer: 9.")], output=["8", "9"], caption="Arguments match parameters by position, left to right."))]),
     F("5.3", "return-values.html", after=[see(annot_code("return sends a value back", "def double(x):\n    return x * 2\n\ny = double(5)\nprint(y)",
              [(1, "return x * 2", "return hands a value back to the caller and ends the function."), (3, "double(5)", "The call is replaced by the value it returns: 10."), (3, "y =", "Store it, or the value is lost."), (4, "print(y)", "Shows 10.")], output=["10"], caption="print shows a value on screen. return gives it back to the program."),
            tbl(["", "print", "return"], [["What it does", "shows text on the screen", "sends a value back to the code that called the function"], ["Can you store the result?", "no", "yes: <code>y = double(5)</code>"], ["Ends the function?", "no", "yes"]]))]),
     F("5.4", "return-decisions-loops.html", after=[see(annot_code("Count with a loop, then return", "def count_evens(nums):\n    count = 0\n    for n in nums:\n        if n % 2 == 0:\n            count = count + 1\n    return count\n\nprint(count_evens([1, 2, 4]))",
              [(1, "count = 0", "Start the counter before the loop."), (3, "n % 2 == 0", "Selection inside iteration."), (5, "return count", "Outside the loop: returns once, after every item is checked."), (7, "[1, 2, 4]", "Two even numbers, so the answer is 2.")], output=["2"], caption="A return inside the loop would end the function after the first item."))]),
     F("5.5", "libraries-apis.html", after=[see(annot_code("Using a library", "import math\n\nprint(math.sqrt(81))\nprint(round(3.14159, 2))",
              [(0, "import math", "Loads the math library."), (2, "math.sqrt", "Library name, a dot, then the procedure name."), (2, "81", "The argument. sqrt returns 9.0."), (3, "round(3.14159, 2)", "Built in, no import needed. The 2 is the number of decimal places.")], output=["9.0", "3.14"], caption="You only need to call a library procedure correctly, not know how it works inside."))]),
     F("5.6", "procedures-create-task.html", after=[see(annot_code("What the Create Task looks for", "def count_over(nums, limit):\n    count = 0\n    for n in nums:\n        if n > limit:\n            count = count + 1\n    return count",
              [(0, "limit", "A parameter that changes the result."), (1, "count = 0", "Sequencing: steps run in order."), (2, "for n in nums:", "Iteration, and it uses the list."), (3, "n > limit", "Selection that depends on the parameter."), (5, "return count", "Returns the result to the caller.")], caption="One procedure can show sequencing, selection, and iteration all at once."))])],
    glossary=[("Function", "A named block of code you can run by calling its name."), ("Procedure", "The exam's word for a named block of code that may take parameters and may return a value."), ("Parameter", "A variable in the function header that receives a value."), ("Argument", "The actual value you pass in when you call the function."),
        ("Call", "Running a function by writing its name and arguments."), ("Return value", "The value a function sends back with return."), ("Library", "A collection of ready-made procedures, like math or random."), ("API", "Application program interface: the description of how to use a library's procedures."),
        ("Documentation", "The text that explains what each procedure does and what it needs."), ("import", "Loads a library so you can use it."), ("Abstraction", "Hiding the details so you can think about what something does, not how."), ("Procedural abstraction", "Naming a block of code so you can use it without thinking about how it works.")],
    cheat=[sec("Function patterns", tbl(["Pattern", "Code"], [["Define", "<code>def name(param1, param2):</code>"], ["Call", "<code>name(arg1, arg2)</code>"], ["Return and store", "<code>result = name(arg1, arg2)</code>"], ["Import and use", "<code>import math</code>, then <code>math.sqrt(16)</code>"], ["Built-ins", "<code>len</code> <code>abs</code> <code>round</code> <code>min</code> <code>max</code> <code>pow</code>"]]))], seed=5)
